/bin/bash -lc "curl -L --max-time 20 -s 'https://unsplash.com/napi/search/photos?query=indoor%20bouldering&per_page=3' -o /tmp/tidepool-photos.json && python - <<'PY'
import json
try:
 data=json.load(open('/tmp/tidepool-photos.json'))
 for p in data.get('results',[]): print(p['urls']['regular'],p.get('alt_description'))
except Exception as e: print(e)
PY"

