<script>
const contactModal=document.getElementById('"'contact-modal');
const tourModal=document.getElementById('tour-modal');
const featureData={memberships:{heading:'Your regulars, all in one place.',detail:'See every member’s plan, payment status, and check-in history. Set up recurring memberships and make changes without a spreadsheet in sight.',result:'✓ Jamie’s monthly membership renewed. One less thing to chase.'},bookings:{heading:'From “Can I book?” to “See you there.”',detail:'Publish your class schedule, set capacity, and let climbers reserve their place. When a class fills up, a waitlist keeps the next spot moving.',result:'✓ Intro to bouldering · Wednesday, 6 pm · 2 spaces available'},passes:{heading:'A warm welcome, without the wait.',detail:'Let visitors pick up a day pass or punch card online. Your front desk can find their pass and check them in, ready for their first climb.',result:'✓ Alex’s day pass is ready. Let’s get climbing.'}};
function selectTab(name){const data=featureData[name]||featureData.memberships;document.getElementById('demo-heading').textContent=data.heading;document.getElementById('demo-detail').textContent=data.detail;document.getElementById('demo-result').textContent=data.result;document.getElementById('demo-panel').setAttribute('aria-labelledby','tab-'+name);document.querySelectorAll('[data-tab]').forEach(tab=>{const active=tab.dataset.tab===name;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;});}
function openModal(modal){document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());modal.showModal();document.body.classList.add('modal-open');}
document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();if(button.dataset.action==='demo')openModal(contactModal);else{selectTab(button.dataset.feature||'memberships');openModal(tourModal);}}));
document.querySelectorAll('.close-modal').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>{if("'!document.querySelector('"'dialog[open]'))document.body.classList.remove('modal-open');});dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();}});});
